163	def _reset_revised_flag(decomp_path):
164	    """Remove ``revised`` key from decomposition frontmatter.
165	
166	    The revise_decomp completion poller treats *any* non-None value
167	    (including False) as "completed".  Removing the key forces it back to
168	    "pending" so the revise agent is actually launched.
169	    """
170	    from artifact_utils import read_frontmatter
171	    data, body = read_frontmatter(decomp_path)
172	    if data and "revised" in data:
173	        del data["revised"]
174	        with open(decomp_path, "w") as f:
175	            f.write("---\n")
176	            f.write(yaml.dump(data, default_flow_style=False, sort_keys=False))
177	            f.write("---\n")
178	            f.write(body)
