181	def _run_script(cmd):
182	    result = subprocess.run(
183	        cmd, shell=True, capture_output=True, text=True)
184	    if result.returncode != 0:
185	        print("Script failed (exit code "
186	              f"{result.returncode})", file=sys.stderr)
187	        if result.stderr:
188	            print(result.stderr, file=sys.stderr)
189	        sys.exit(1)
190	    return result.stdout.strip()
