193	def _compute_ai_scores(ids_file):
194	    """Compute AI implementability scores from signal values in epic frontmatter."""
195	    ids = _read_ids(ids_file)
196	    if not ids:
197	        return
198	    cmd = f"python3 scripts/compute_ai_scores.py {' '.join(ids)}"
199	    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
200	    if result.stderr:
201	        print(result.stderr, file=sys.stderr)
