204	# ---------- Transition logic ----------
205	
206	MAIN_SEQUENCE = ["FETCH", "DECOMPOSE", "REVIEW_DECOMP"]
207	
208	
209	def advance(state, dry_run=False):
210	    """Compute and apply the next phase transition.
211	
212	    Returns (next_phase, summary_line).
213	    """
214	    phase = state["phase"]
215	
216	    # --- BATCH_START: reset counters, populate active IDs ---
217	    if phase == "BATCH_START":
218	        batch = state.get("batch", 0) + 1
219	        if not dry_run:
220	            state["batch"] = batch
221	            batch_file = f"tmp/pipeline-batch-{batch}-ids.txt"
222	            _copy_ids(batch_file, "tmp/pipeline-active-ids.txt")
223	        return "FETCH", f"BATCH_START → FETCH: batch={batch}"
224	
225	    # --- Linear main sequence ---
226	    if phase in MAIN_SEQUENCE[:-1]:
227	        nxt = MAIN_SEQUENCE[MAIN_SEQUENCE.index(phase) + 1]
228	        if phase == "DECOMPOSE" and not dry_run:
229	            _compute_ai_scores("tmp/pipeline-active-ids.txt")
230	        return nxt, f"{phase} → {nxt}"
231	
232	    # --- REVIEW_DECOMP → REVISE_DECOMP (unconditional first revision) ---
233	    if phase == "REVIEW_DECOMP":
234	        if not dry_run:
235	            # Clear the ``revised`` default so the poller sees IDs as pending.
236	            # The schema sets revised: false on creation, but the poller
237	            # treats any non-None value as "completed".
238	            for strat_id in _read_ids("tmp/pipeline-active-ids.txt"):
239	                decomp = f"artifacts/epic-tasks/{strat_id}-decomposition.md"
240	                if os.path.exists(decomp):
241	                    _reset_revised_flag(decomp)
242	        return "REVISE_DECOMP", "REVIEW_DECOMP → REVISE_DECOMP: first revision (unconditional)"
243	
244	    # --- REVISE_DECOMP → RE_REVIEW_CHECK ---
245	    if phase == "REVISE_DECOMP":
246	        if not dry_run:
247	            _compute_ai_scores("tmp/pipeline-active-ids.txt")
248	        return "RE_REVIEW_CHECK", "REVISE_DECOMP → RE_REVIEW_CHECK"
249	
250	    # --- RE_REVIEW_CHECK: did revision change anything? ---
251	    if phase == "RE_REVIEW_CHECK":
252	        from artifact_utils import read_frontmatter
253	        cycle = state.get("revise_cycle", 0)
254	        if cycle == 0:
255	            check_ids = _read_ids("tmp/pipeline-active-ids.txt")
256	        else:
257	            check_ids = _read_ids("tmp/pipeline-revise-ids.txt")
258	        revised_ids = []
259	        for strat_id in check_ids:
260	            decomp_path = f"artifacts/epic-tasks/{strat_id}-decomposition.md"
261	            if os.path.exists(decomp_path):
262	                try:
263	                    data, _ = read_frontmatter(decomp_path)
264	                    if data and data.get("revised"):
265	                        revised_ids.append(strat_id)
266	                except Exception:
267	                    pass
268	        if not revised_ids:
269	            return "BATCH_DONE", "RE_REVIEW_CHECK → BATCH_DONE: revision made no changes"
270	        if not dry_run:
271	            _write_ids("tmp/pipeline-revise-ids.txt", revised_ids)
272	            # Delete old review files so the poller can detect fresh reviews
273	            for strat_id in revised_ids:
274	                review_path = f"artifacts/epic-reviews/{strat_id}-decomp-review.md"
275	                if os.path.exists(review_path):
276	                    os.remove(review_path)
277	        return ("RE_REVIEW",
278	                f"RE_REVIEW_CHECK → RE_REVIEW: {len(revised_ids)} revised")
279	
280	    # --- RE_REVIEW → REVISE_CHECK ---
281	    if phase == "RE_REVIEW":
282	        return "REVISE_CHECK", "RE_REVIEW → REVISE_CHECK"
283	
284	    # --- REVISE_CHECK: only revise again if review fails, with cycle cap ---
285	    if phase == "REVISE_CHECK":
286	        from artifact_utils import read_frontmatter
287	        revise_ids = _read_ids("tmp/pipeline-revise-ids.txt")
288	        failing_ids = []
289	        for strat_id in revise_ids:
290	            review_path = f"artifacts/epic-reviews/{strat_id}-decomp-review.md"
291	            if os.path.exists(review_path):
292	                try:
293	                    data, _ = read_frontmatter(review_path)
294	                    if data and not data.get("pass", True):
295	                        failing_ids.append(strat_id)
296	                except Exception:
297	                    pass
298	        cycle = state.get("revise_cycle", 0)
299	        if failing_ids and cycle < 2:
300	            if not dry_run:
301	                state["revise_cycle"] = cycle + 1
302	                _write_ids("tmp/pipeline-revise-ids.txt", failing_ids)
303	                # Reset revised flag so poller detects new changes
304	                for strat_id in failing_ids:
305	                    decomp_path = f"artifacts/epic-tasks/{strat_id}-decomposition.md"
306	                    if os.path.exists(decomp_path):
307	                        _reset_revised_flag(decomp_path)
308	            return ("RE_REVISE",
309	                    f"REVISE_CHECK → RE_REVISE:"
310	                    f" failing={len(failing_ids)} cycle={cycle + 1}/2")
311	        return "BATCH_DONE", "REVISE_CHECK → BATCH_DONE: review passed or cycle cap reached"
312	
313	    # --- RE_REVISE → RE_REVIEW_CHECK (loop back) ---
314	    if phase == "RE_REVISE":
315	        if not dry_run:
316	            _compute_ai_scores("tmp/pipeline-revise-ids.txt")
317	        return "RE_REVIEW_CHECK", "RE_REVISE → RE_REVIEW_CHECK"
318	
319	    # --- BATCH_DONE decision ---
320	    if phase == "BATCH_DONE":
321	        batch = state.get("batch", 0)
322	        total = state.get("total_batches", 1)
323	        retry = state.get("retry_cycle", 0)
324	        active_ids = _read_ids("tmp/pipeline-active-ids.txt")
325	        batch_stats = f"{len(active_ids)} strategies"
326	        prefix = "Retry batch" if retry > 0 else "Batch"
327	        summary = f"{prefix} {batch}/{total} complete: {batch_stats}"
328	        if batch < total:
329	            return ("BATCH_START",
330	                    f"{summary}\nBATCH_DONE → BATCH_START")
331	        if retry < 1:
332	            # Check for errors
333	            all_ids = _read_ids("tmp/pipeline-all-ids.txt")
334	            error_ids = []
335	            for strat_id in all_ids:
336	                review_path = f"artifacts/epic-reviews/{strat_id}-decomp-review.md"
337	                if os.path.exists(review_path):
338	                    try:
339	                        from artifact_utils import read_frontmatter
340	                        data, _ = read_frontmatter(review_path)
341	                        if data and data.get("error"):
342	                            error_ids.append(strat_id)
343	                    except Exception:
344	                        pass
345	                decomp_path = f"artifacts/epic-tasks/{strat_id}-decomposition.md"
346	                if not os.path.exists(decomp_path):
347	                    error_ids.append(strat_id)
348	            error_ids = list(dict.fromkeys(error_ids))
349	            if error_ids:
350	                return ("ERROR_COLLECT",
351	                        f"{summary}\nBATCH_DONE → ERROR_COLLECT:"
352	                        f" errors={len(error_ids)}")
353	        return "REPORT", f"{summary}\nBATCH_DONE → REPORT"
354	
355	    # --- ERROR_COLLECT → BATCH_START ---
356	    if phase == "ERROR_COLLECT":
357	        retry_ids = _read_ids("tmp/pipeline-retry-ids.txt")
358	        n = len(retry_ids)
359	        batch = state.get("total_batches", 0)
360	        return ("BATCH_START",
361	                f"ERROR_COLLECT: retry batch {batch} with {n} error IDs\n"
362	                f"ERROR_COLLECT → BATCH_START")
363	
364	    # --- REPORT → DONE (with optional announce) ---
365	    if phase == "REPORT":
366	        if not dry_run and state.get("announce_complete"):
367	            _run_script("python3 scripts/finish.py")
368	        return "DONE", "REPORT → DONE"
369	
370	    print(f"No transition defined for phase: {phase}", file=sys.stderr)
371	    sys.exit(1)
